    : digest_{sha1_digest(reinterpret_cast<const std::uint8_t*>(text.data()), text.size())} {}

SHA1::SHA1(std::istream& in) {
  auto bytes = read_all(in);
  digest_ = sha1_digest(bytes.data(), bytes.size());
}

