std::array<std::uint8_t, 32> sha256_digest(const std::uint8_t* msg, std::size_t len) {
  std::uint32_t h[8] = {
    0x6a09e667u, 0xbb67ae85u, 0x3c6ef372u, 0xa54ff53au,
    0x510e527fu, 0x9b05688cu, 0x1f83d9abu, 0x5be0cd19u
  };

  const std::uint64_t bit_len = static_cast<std::uint64_t>(len) * 8ull;

  std::vector<std::uint8_t> buffer(msg, msg + len);
  buffer.push_back(0x80u);
  while ((buffer.size() % 64) != 56) {
    buffer.push_back(0x00u);
  }
  for (int i = 7; i >= 0; --i) {
    buffer.push_back(static_cast<std::uint8_t>((bit_len >> (8 * i)) & 0xffu));
  }

  std::uint32_t w[64];

  for (std::size_t offset = 0; offset < buffer.size(); offset += 64) {
    for (int i = 0; i < 16; ++i) {
      const std::size_t j = offset + static_cast<std::size_t>(i) * 4;
      w[i] = (static_cast<std::uint32_t>(buffer[j + 0]) << 24) |
             (static_cast<std::uint32_t>(buffer[j + 1]) << 16) |
             (static_cast<std::uint32_t>(buffer[j + 2]) << 8) |
             (static_cast<std::uint32_t>(buffer[j + 3]) << 0);
    }
    for (int i = 16; i < 64; ++i) {
      w[i] = small_sigma1(w[i - 2]) + w[i - 7] + small_sigma0(w[i - 15]) + w[i - 16];
    }

    std::uint32_t a = h[0];
    std::uint32_t b = h[1];
    std::uint32_t c = h[2];
    std::uint32_t d = h[3];
    std::uint32_t e = h[4];
    std::uint32_t f = h[5];
    std::uint32_t g = h[6];
    std::uint32_t hh = h[7];

    for (int i = 0; i < 64; ++i) {
      const std::uint32_t t1 = hh + big_sigma1(e) + ch(e, f, g) + k[i] + w[i];
      const std::uint32_t t2 = big_sigma0(a) + maj(a, b, c);

      hh = g;
      g = f;
      f = e;
      e = d + t1;
      d = c;
      c = b;
      b = a;
      a = t1 + t2;
    }

    h[0] += a;
    h[1] += b;
    h[2] += c;
    h[3] += d;
    h[4] += e;
    h[5] += f;
    h[6] += g;
    h[7] += hh;
  }

  std::array<std::uint8_t, 32> out{};
  for (int i = 0; i < 8; ++i) {
    out[static_cast<std::size_t>(i) * 4 + 0] = static_cast<std::uint8_t>((h[i] >> 24) & 0xffu);
    out[static_cast<std::size_t>(i) * 4 + 1] = static_cast<std::uint8_t>((h[i] >> 16) & 0xffu);
    out[static_cast<std::size_t>(i) * 4 + 2] = static_cast<std::uint8_t>((h[i] >> 8) & 0xffu);
    out[static_cast<std::size_t>(i) * 4 + 3] = static_cast<std::uint8_t>((h[i] >> 0) & 0xffu);
  }
  return out;
}

